export function getOrigamiModel(id) {
  return ORIGAMI_MODELS.find((model) => model.id === id) || null;
}

export function textFor(value, locale = "en") {
  if (typeof value === "string") return value;
  if (!value) return "";
  return value[locale] || value.en || Object.values(value)[0] || "";
}
